<?php get_header(); ?><section class="wrap"><div class="archive-head"><h1><?php if(is_search())echo 'Поиск: '.esc_html(get_search_query());else the_archive_title(); ?></h1><?php if(!is_search())the_archive_description(); ?></div><?php if(is_post_type_archive('kl_project')||is_tax('kl_project_type')): ?><nav class="filter-nav" aria-label="Тип проекта"><a href="<?php echo kl_url('projects');?>">Все</a><?php foreach(get_terms(['taxonomy'=>'kl_project_type','hide_empty'=>false]) as $term):?><a href="<?php echo esc_url(get_term_link($term)); ?>"><?php echo esc_html($term->name); ?></a><?php endforeach;?></nav><?php endif;?><div class="post-grid"><?php $has_results=have_posts();while(have_posts()):the_post(); ?><article class="post-card"><a href="<?php the_permalink(); ?>"><img src="<?php echo kl_image(get_the_ID(),'linea-house');?>" alt="<?php echo esc_attr(get_the_title()); ?>" loading="lazy"><h2><?php the_title(); ?></h2></a><?php the_excerpt(); ?></article><?php endwhile;?></div><?php if(!$has_results):?><p>Ничего не найдено. Попробуйте другой запрос.</p><?php endif;?><div class="pagination"><?php echo paginate_links(['prev_text'=>'Назад','next_text'=>'Далее']);?></div></section><?php get_footer();?>
